import six
import logging
from abc import ABCMeta, abstractmethod
from ute_ue.utils.param_checker import tput_user_value2normalized
from taf.analyzer.iperf_throughput.facade import IperfThroughput
from taf.ue.mtk.exceptions import NoSumStatError


@six.add_metaclass(ABCMeta)
class ThroughputChecker(object):
    @abstractmethod
    def __init__(self, **kwargs):
        pass

    @abstractmethod
    def setup(self):
        pass

    @abstractmethod
    def calculate_throughput(self):
        pass

    @abstractmethod
    def teardown(self):
        pass


class IperfThroughputChecker(ThroughputChecker):

    def __init__(self, logger=None):
        super(IperfThroughputChecker, self).__init__()
        self.logger = logger or logging
        self._throughput_analyzer = None
        self._throughput = None
        self._throughput_records_output = {}
        self._avg_tput = None
        self._min_tput = None
        self._max_tput = None

    @property
    def throughput(self):
        return self._throughput

    def setup(self):
        self._throughput_analyzer = IperfThroughput()

    def create_iperf_throughput(self, file_path, protocol, time_range, column=None):
        if protocol == 'udp':
            self._throughput = self._throughput_analyzer.create_iperf_server_udp_throughput(
                column=column,
                log=file_path,
                time_range=time_range,
                throughput_records_output=self._throughput_records_output)
        else:
            self._throughput = self._throughput_analyzer.create_iperf_server_tcp_throughput(
                column=column,
                log=file_path,
                time_range=time_range,
                throughput_records_output=self._throughput_records_output)

    def create_iperf3_throughput(self, file_path, protocol, time_range, column=None):
        if protocol == 'udp':
            self._throughput = self._throughput_analyzer.create_iperf3_server_udp_throughput(
                column=column,
                log=file_path,
                time_range=time_range,
                throughput_records_output=self._throughput_records_output)
        else:
            self._throughput = self._throughput_analyzer.create_iperf3_server_tcp_throughput(
                column=column,
                log=file_path,
                time_range=time_range,
                throughput_records_output=self._throughput_records_output)

    def calculate_throughput(self):
        # iperf throughput is a list[dict], e.g.
        # [{'connection':
        #     {'connection_id': '3', 'server_addr': '10.44.35.224',
        #     'server_port': '50006', 'client_addr': '10.47.55.164', 'client_port': '40151'},
        # 'peak': {'value': 5060.0, 'unit': 'Kbits/sec'},
        # 'average': {'value': 5000.0, 'unit': 'Kbits/sec'},
        # 'minimum': {'value': 4950.0, 'unit': 'Kbits/sec'},
        # 'count': 120, 'interval': 120.0}]

        self._throughput_analyzer.analyze(throughputs=[self._throughput, ])
        throughput_result = self._throughput_analyzer.get_throughput(throughput=self._throughput)
        return [item.to_dict() for item in throughput_result]

    @staticmethod
    def _calculate_stream_throughput(throughput_list, throughput_type):
        value_tput = throughput_list[0][throughput_type]['value']
        unit_tput = throughput_list[0][throughput_type]['unit']
        stream_tput = '{value}{unit}'.format(value=value_tput, unit=unit_tput)
        return tput_user_value2normalized(stream_tput)

    @staticmethod
    def _calculate_streams_throughput(throughput_list, throughput_type):
        streams_tput = None
        for connection in throughput_list:
            if connection['connection']['connection_id'] == 'SUM':
                value_tput = connection[throughput_type]['value']
                unit_tput = connection[throughput_type]['unit']
                streams_tput = '{value}{unit}'.format(value=value_tput, unit=unit_tput)
                streams_tput = tput_user_value2normalized(streams_tput)
                break
        else:
            raise NoSumStatError('analyze multiple streams log wrong in taf.analyzer.iperf_throughput')
        return streams_tput

    def _calculate_average_throughput(self, throughput_list, connection_count):
        if connection_count == 1:
            self._avg_tput = self._calculate_stream_throughput(throughput_list, 'average')
        else:
            sum_total = 0.0
            time_escape = 0
            for connection in throughput_list:
                if connection['connection']['connection_id'] == 'SUM':  # for taf.analyzer.iperf_throughput >=0.6.0
                    average_total = connection['average']['value']
                    break
                sum_per_connection = connection['average']['value'] * connection['interval']
                sum_total = sum_total + sum_per_connection
                time_escape = time_escape + connection['interval']
            else:  # for taf.analyzer.iperf_throughput <0.6.0
                average_total = sum_total / time_escape * connection_count
            unit = throughput_list[0]['average']['unit']
            average_throughput = '{value}{unit}'.format(value=average_total, unit=unit)
            self._avg_tput = tput_user_value2normalized(average_throughput)
        self.logger.info("Average throughput is {} Kbits/sec".format(self._avg_tput))

    def _calculate_minimum_throughput(self, throughput_list, connection_count):
        if connection_count == 1:
            self._min_tput = self._calculate_stream_throughput(throughput_list, 'minimum')
        else:
            self._min_tput = self._calculate_streams_throughput(throughput_list, 'minimum')

    def _calculate_maximum_throughput(self, throughput_list, connection_count):
        if connection_count == 1:
            self._max_tput = self._calculate_stream_throughput(throughput_list, 'peak')
        else:
            self._max_tput = self._calculate_streams_throughput(throughput_list, 'peak')

    def get_average_throughput(self):
        throughput_list = self.calculate_throughput()
        self._calculate_average_throughput(throughput_list, len(throughput_list))
        return self._avg_tput

    def get_throughput_statistics(self):
        throughput_list = self.calculate_throughput()
        self._calculate_average_throughput(throughput_list, len(throughput_list))
        self._calculate_minimum_throughput(throughput_list, len(throughput_list))
        self._calculate_maximum_throughput(throughput_list, len(throughput_list))

        unit_stat = 'kbits/sec'
        avg_stat = '{}{}'.format(self._avg_tput, unit_stat)
        min_stat = '{}{}'.format(self._min_tput, unit_stat)
        max_stat = '{}{}'.format(self._max_tput, unit_stat)
        self.logger.info("data transfer statistics:\navg: {}\nmin: {}\nmax: {}".format(avg_stat,
                                                                                       min_stat,
                                                                                       max_stat))
        self.logger.info("RAW interval values: \n{}".format(self._throughput_records_output))
        return {'average_statistics': avg_stat,
                'minimum_statistics': min_stat,
                'maximum_statistics': max_stat,
                'raw_statistics': self._throughput_records_output}

    def teardown(self):
        pass
